-- Exported from project swiftborder (traffic_prediction.v_training_set) on 2026-09-26 via INFORMATION_SCHEMA.TABLES.

CREATE OR REPLACE VIEW `swiftborder.traffic_prediction.v_training_set`
AS WITH b AS (SELECT * FROM `swiftborder.traffic_prediction.v_bins_10min`), f AS (SELECT route_id, direction, bin_ts, bin_sgt, dur_min, congestion_ratio, speed_kmh, gap_min, LAG(dur_min, 1) OVER w AS lag_10, LAG(dur_min, 2) OVER w AS lag_20, LAG(dur_min, 3) OVER w AS lag_30, LAG(dur_min, 6) OVER w AS lag_60, AVG(dur_min) OVER (PARTITION BY route_id ORDER BY bin_ts ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS roll_mean_30, AVG(dur_min) OVER (PARTITION BY route_id ORDER BY bin_ts ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS roll_mean_60, LAG(dur_min, 1) OVER w - LAG(dur_min, 4) OVER w AS slope_30, MAX(IF(gap_min > 25, 1, 0)) OVER (PARTITION BY route_id ORDER BY bin_ts ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS after_gap, LEAD(dur_min, 3) OVER w AS y_30, LEAD(dur_min, 6) OVER w AS y_60, EXTRACT(HOUR FROM bin_sgt) * 60 + EXTRACT(MINUTE FROM bin_sgt) AS tod_min, EXTRACT(DAYOFWEEK FROM bin_sgt) AS dow, DATE(bin_sgt) AS date_sgt FROM b WINDOW w AS (PARTITION BY route_id ORDER BY bin_ts)) SELECT route_id, direction, bin_ts, bin_sgt, date_sgt, dur_min AS y_persistence, congestion_ratio, speed_kmh, IF(after_gap = 1, NULL, lag_10) AS lag_10, IF(after_gap = 1, NULL, lag_20) AS lag_20, IF(after_gap = 1, NULL, lag_30) AS lag_30, IF(after_gap = 1, NULL, lag_60) AS lag_60, IF(after_gap = 1, NULL, roll_mean_30) AS roll_mean_30, IF(after_gap = 1, NULL, roll_mean_60) AS roll_mean_60, IF(after_gap = 1, NULL, slope_30) AS slope_30, after_gap, SIN(2 * ACOS(-1) * tod_min / 1440) AS tod_sin, COS(2 * ACOS(-1) * tod_min / 1440) AS tod_cos, tod_min / 5.0 AS tod_block, dow, IF(dow IN (1, 7), 1, 0) AS is_weekend, IF(EXTRACT(HOUR FROM bin_sgt) BETWEEN 6 AND 10, 1, 0) AS is_morning_peak, IF(EXTRACT(HOUR FROM bin_sgt) BETWEEN 16 AND 21, 1, 0) AS is_evening_peak, y_30, y_60 FROM f;
